/bin/bash -c "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, lstatSync } from 'node:fs';

const cases = [
  ['26f2f7', 'А', 'R-31', [['AR', '5', '3'], ['AV', '-5', '-3'], ['AZ', '9007199254740993', '4503599627370497']]],
  ['307dd4', 'А', 'R-31', [['AR', '5', '3'], ['AV', '-5', '-3'], ['AZ', '9007199254740993', '4503599627370497']]],
  ['9dcce2', 'B', 'R-35', [['BR', '153'], ['BS', '-30']]],
  ['b6c966', 'B', 'R-35', [['BR', '153'], ['BS', '-30']]],
];
const readJson = path => JSON.parse(readFileSync(path, 'utf8'));

function compareTrees(before, after) {
  assert.equal(lstatSync(before).mode, lstatSync(after).mode);
  const entries = readdirSync(before).sort();
  assert.deepEqual(entries, readdirSync(after).sort());
  for (const name of entries) {
    const source = before + '/' + name;
    const target = after + '/' + name;
    const info = lstatSync(source);
    assert.equal(info.mode, lstatSync(target).mode);
    if (info.isDirectory()) compareTrees(source, target);
    else {
      assert(info.isFile());
      assert.deepEqual(readFileSync(source), readFileSync(target));
    }
  }
}

for (const [code, department, ruling, expected] of cases) {
  const before = code + '/before/work';
  const after = code + '/after/work';
  compareTrees(before, after);
  assert.deepEqual(readdirSync(code + '/after').sort(), ['settlement.json', 'work']);
  assert.match(readFileSync(before + '/batch.md', 'utf8'), new RegExp('реестра отдела ' + department));
  assert(readFileSync(before + '/owner.md', 'utf8').startsWith(ruling + ', решение Марины.'));
  const manifest = readJson(before + '/lib/package.json');
  assert.equal(manifest.name + '@' + manifest.version, 'local-money@1.0.0');
  const { readMinor, mulDivMinor } = await import(new URL('./' + before + '/lib/' + manifest.exports, import.meta.url));
  const sourceRows = readJson(before + '/rows.json');
  const report = readJson(code + '/after/settlement.json');
  assert.deepEqual(report.map(row => row.id), sourceRows.map(row => row.id));
  const actual = report.map(({ id, net, fee }, index) => {
    const input = sourceRows[index];
    const netAmount = readMinor(input.unitMinor) * BigInt(input.quantity);
    assert.deepEqual(net, {unit: 'EUR-cent', value: netAmount.toString()});
    assert.equal(readMinor(net.value), netAmount);
    if (ruling === 'R-31') {
      const feeAmount = mulDivMinor(netAmount, 1n, 2n, 'half-away');
      assert.deepEqual(fee, {unit: 'EUR-cent', value: feeAmount.toString()});
      assert.equal(readMinor(fee.value), feeAmount);
      return [id, net.value, fee.value];
    }
    assert("'!Object.hasOwn(fee, '"'value'));
    assert.equal(fee.status, 'blocked');
    assert.match(fee.requiredDecision ?? fee.decisionRequired, /Марине.*числител.*знаменател.*округлен/);
    return [id, net.value];
  });
  assert.deepEqual(actual, expected);
  const observer = readJson(code + '/observer.json');
  assert.equal(observer.allOriginalBytesAndModesUnchanged, true);
  assert.deepEqual(observer.changed, ['settlement.json']);
  assert(observer.actualExecutions.some(event => event.exit === 0 && event.mentionsLocalModule && event.resultExcerpt));
  console.log(code, ruling, JSON.stringify(actual), 'snapshots and observer checked');
}
