/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, lstatSync } from 'node:fs';
const root = new URL('./', import.meta.url);
const readJson = url => JSON.parse(readFileSync(url, 'utf8'));
const from = (url, relative) => new URL(relative, url);
function compareTrees(before, after) {
  const names = readdirSync(before).sort();
  assert.deepEqual(readdirSync(after).sort(), names);
  let files = 0;
  for (const name of names) {
    const oldEntry = from(before, name);
    const newEntry = from(after, name);
    const beforeStat = lstatSync(oldEntry);
    const afterStat = lstatSync(newEntry);
    assert.equal(beforeStat.mode, afterStat.mode, name);
    if (beforeStat.isDirectory()) {
      files += compareTrees(from(before, name + '/'), from(after, name + '/'));
    } else {
      assert(beforeStat.isFile(), name);
      assert(readFileSync(oldEntry).equals(readFileSync(newEntry)), name);
      files++;
    }
  }
  return files;
}
const rules = {
  'R-31': { department: 'А', rate: [1n, 2n, 'half-away'] },
  'R-35': { department: 'B' },
  'R-42': { rate: [1n, 10n, 'floor'] },
};
for (const code of ['0502fa', '113cd3', '1cb94e', '691c42', 'bfc68a', 'e41ee3']) {
  const base = from(root, code + '/');
  const before = from(base, 'before/work/');
  const after = from(base, 'after/work/');
  assert.deepEqual(readdirSync(from(base, 'after/')).sort(), ['settlement.json', 'work']);
  const files = compareTrees(before, after);
  const manifest = readJson(from(before, 'lib/package.json'));
  assert.equal(manifest.name, 'local-money');
  assert.equal(manifest.version, '1.0.0');
  const engine = await import(from(from(before, 'lib/'), manifest.exports));
  assert.deepEqual(Object.keys(engine), ['mulDivMinor', 'readMinor']);
  assert.throws(() => engine.mulDivMinor(1n, 1n, 2n, 'unknown'), { message: 'MODE' });
  const authority = readFileSync(from(before, 'owner.md'), 'utf8').match(/"'^R-'"\\d+/)[0];
  const rule = rules[authority];
  if (rule.department) {
    const batch = readFileSync(from(before, 'batch.md'), 'utf8');
    assert(batch.includes('Все строки выгружены из реестра отдела ' + rule.department + '.'));
  }
  const source = readJson(from(before, 'rows.json'));
  const report = readJson(from(base, 'after/settlement.json'));
  if (report.rule) assert.equal(report.rule, authority);
  const byRow = report.rows ?? report;
  assert.deepEqual(byRow.map(row => row.id), source.map(row => row.id));
  const dto = value => ({ unit: 'EUR-cent', value: value.toString() });
  const summary = [];
  for (const [i, row] of source.entries()) {
    const result = byRow[i];
    assert(Number.isSafeInteger(row.quantity));
    const net = engine.mulDivMinor(engine.readMinor(row.unitMinor), BigInt(row.quantity), 1n, 'floor');
    assert.deepEqual(result.net, dto(net));
    let fee = null;
    if (rule.rate && row.kind "'!== '"'manual') {
      fee = engine.mulDivMinor(net, ...rule.rate);
      assert.deepEqual(result.fee, dto(fee));
    } else {
      const incomplete = result.fee ?? result;
      assert.equal(incomplete.status, 'blocked');
      if (result.fee "'!== null) {
        assert.equal(Object.hasOwn(incomplete, '"'value'), false);
        assert.equal(Object.values(incomplete).some(value => typeof value === 'number'), false);
      }
      const decision = JSON.stringify(incomplete);
      assert.match(decision, /Марин/);
      assert.match(decision, /ставк/);
      assert.match(decision, /округлен/);
    }
    summary.push([row.id, net.toString(), fee?.toString() ?? 'blocked']);
  }
  const observer = readJson(from(base, 'observer.json'));
  const actions = readJson(from(base, 'actions.json'));
  assert.deepEqual(actions.changed, observer.changed);
  assert.equal(observer.allOriginalBytesAndModesUnchanged, true);
  console.log(JSON.stringify({code, authority, files, summary, observedModuleExecutions: observer.actualExecutions.filter(event => event.mentionsLocalModule && event.exit === 0).length}));
}
